        </div>
      </div>

      {/* GRÁFICOS */}
      <div className="space-y-8 md:space-y-12">
        {activeTab === 'special' && (
          <div className="bg-white dark:bg-slate-900 p-6 md:p-10 rounded-[32px] md:rounded-[48px] shadow-sm border border-slate-200 dark:border-slate-800 transition-colors">
