                {categories.length} Tipos
              </span>
            </div>

            <div className="divide-y divide-slate-100 dark:divide-slate-800">
              {categories.length === 0 ? (
                <div className="p-10 text-center text-slate-400 dark:text-slate-600">
                  <p>Nenhum tipo de serviço configurado.</p>
